python
import asyncio
from fastapi import FastAPI
from fastapi.responses import JSONResponse, HTMLResponse
from jinja2 import Environment, FileSystemLoader, select_autoescape
from playwright.async_api import async_playwright

env = Environment(
    loader=FileSystemLoader("."),
    autoescape=select_autoescape()
)
app = FastAPI()

# ----------- BOLTOK AKCIÓK GYŰJTÉSE (csak JYSK példa, bővíthető ugyanígy) -----------

async def get_jysk_deals():
    deals = []
    url = "https://jysk.hu/akciok"
    async with async_playwright() as p:
        browser = await p.chromium.launch(headless=True)
        page = await browser.new_page()
        await page.goto(url, timeout=60000)
        items = await page.query_selector_all(".product-list__item")
        for item in items:
            try:
                name = await item.query_selector_eval('.product-list__name', 'el => el.textContent')
                orig = await item.query_selector_eval('.product-list__old-price', 'el => el.textContent', strict=False)
                sale = await item.query_selector_eval('.product-list__price', 'el => el.textContent')
                link = await item.query_selector_eval('a', 'el => el.href')
                orig_num = 0.0
                sale_num = 0.0
                if orig:
                    orig_num = float(''.join(ch for ch in orig.replace('.', '').replace(',', '.').replace(' ', '') if ch.isdigit() or ch == '.'))
                    sale_num = float(''.join(ch for ch in sale.replace('.', '').replace(',', '.').replace(' ', '') if ch.isdigit() or ch == '.'))
                    discount = round(100 * (orig_num - sale_num) / orig_num) if orig_num > 0 else 0
                else:
                    sale_num = float(''.join(ch for ch in sale.replace('.', '').replace(',', '.').replace(' ', '') if ch.isdigit() or ch == '.'))
                    discount = 0
                deals.append({
                    "name": name.strip(),
                    "orig_price": orig.strip() if orig else "",
                    "sale_price": sale.strip(),
                    "discount": discount,
                    "url": link,
                    "source": "JYSK"
                })
            except Exception:
                continue
        await browser.close()
    return deals

# TOVÁBBI webáruházakhoz ugyanilyet írj (keress főoldal-by-oldalbox vagy listában). Pl. get_dm_deals(), get_douglas_deals(), stb.

async def all_deals():
    tasks = [get_jysk_deals()]  # Bontsd ki ha készen vagy több scraperrel!
    results = await asyncio.gather(*tasks)
    all_deals = []
    for r in results:
        all_deals.extend(r)
    return all_deals

@app.get("/api/deals")
async def api_deals():
    deals = await all_deals()
    deals.sort(key=lambda x: x['discount'], reverse=True)
    return JSONResponse(content=deals)

@app.get("/", response_class=HTMLResponse)
async def frontend():
    deals = await all_deals()
    deals.sort(key=lambda x: x['discount'], reverse=True)
    template = env.get_template("index.html")
    return template.render(deals=deals)

if __name__ == "__main__":
    import uvicorn
    uvicorn.run("main:app", host="0.0.0.0", port=8000, reload=True)


